function fusionnerIntervalles(tab) {
  if (tab.length === 0) return [];
  tab.sort((a, b) => a[0] - b[0]);
  const merged = [tab[0]];
  for (let i = 1; i < tab.length; i++) {
    const current = tab[i];
    const last = merged[merged.length - 1];
    if (last[1] >= current[0]) {
      last[1] = Math.max(last[1], current[1]);
    } else {
      merged.push(current);
    }
  }
  return merged;
}

function prefixeCommun(tab) {
  if (tab.length === 0) return "";
  let prefix = tab[0];
  for (let i = 1; i < tab.length; i++) {
    const str = tab[i];
    let j = 0;
    while (j < prefix.length && j < str.length && prefix[j] === str[j]) {
      j++;
    }
    prefix = prefix.substring(0, j);
    if (prefix === "") break;
  }
  return prefix;
}

